// Self-check fixture: implemented chip whose dependency (Mux16.hdl in this
// directory) is still a stub.  Expected result: SKIP, naming the stub.
CHIP Mux4Way16 {
    IN a[16], b[16], c[16], d[16], sel[2];
    OUT out[16];
    PARTS:
    Mux16(a=a, b=b, sel=sel[0], out=ab);
    Mux16(a=c, b=d, sel=sel[0], out=cd);
    Mux16(a=ab, b=cd, sel=sel[1], out=out);
}

// Self-check fixture: wrong combinational chip (Nand instead of And).
// Expected result: FAIL on an exhaustive vector.
CHIP And {
    IN a, b;
    OUT out;
    PARTS:
    Nand(a=a, b=b, out=out);
}

// Self-check fixture: correct ALU (delegates to the built-in ALU, which the
// simulator resolves because no ALU.hdl exists in this directory).
// Expected result: PASS - proves the ALU vector generator is not producing
// vectors that a correct chip fails.
CHIP ALU {
    IN x[16], y[16], zx, nx, zy, ny, f, no;
    OUT out[16], zr, ng;
    PARTS:
    ALU(x=x, y=y, zx=zx, nx=nx, zy=zy, ny=ny, f=f, no=no,
        out=out, zr=zr, ng=ng);
}

// Self-check fixture: ALU with the zr and ng status bits swapped.
// Expected result: FAIL (only detectable on vectors where zr != ng).
CHIP ALU {
    IN x[16], y[16], zx, nx, zy, ny, f, no;
    OUT out[16], zr, ng;
    PARTS:
    ALU(x=x, y=y, zx=zx, nx=nx, zy=zy, ny=ny, f=f, no=no,
        out=out, zr=ng, ng=zr);
}

// Self-check fixture: wrong interface (in[4] instead of in[8]).
// Expected result: FAIL with an interface diagnostic, not a crash.
CHIP Or8Way {
    IN in[4];
    OUT out;
    PARTS:
    Or(a=in[0], b=in[1], out=w0);
    Or(a=in[2], b=in[3], out=w1);
    Or(a=w0, b=w1, out=out);
}

// Self-check fixture: correct PC (delegates to the built-in PC).
// Expected result: PASS - proves the PC step script does not fail a correct
// chip and that tick/tock timing is compared correctly.
CHIP PC {
    IN in[16], load, inc, reset;
    OUT out[16];
    PARTS:
    PC(in=in, load=load, inc=inc, reset=reset, out=out);
}

// Self-check fixture: Bit built from the built-in 16-bit Register, using only
// bit 0.  Expected result: PASS.
CHIP Bit {
    IN in, load;
    OUT out;
    PARTS:
    Register(in[0]=in, load=load, out[0]=out);
}

// Self-check fixture: Register whose load input is inverted.
// Expected result: FAIL after tock.
CHIP Register {
    IN in[16], load;
    OUT out[16];
    PARTS:
    Not(in=load, out=nload);
    ARegister(in=in, load=nload, out=out);
}

// Self-check fixture: "Register" with no clocked element at all - the output
// follows the input immediately.  Expected result: FAIL, first noticed on the
// pre-clock read (the output must still show the stored value there).
CHIP Register {
    IN in[16], load;
    OUT out[16];
    PARTS:
    And16(a=in, b=in, out=out);
}

// Self-check fixture: RAM8 built on the built-in RAM64 but ignoring
// address[2], so addresses 4..7 alias onto 0..3.
// Expected result: FAIL, caught by the aliasing / boundary-address script.
CHIP RAM8 {
    IN in[16], load, address[3];
    OUT out[16];
    PARTS:
    RAM64(in=in, load=load,
          address[0]=address[0], address[1]=address[1], out=out);
}

// Self-check fixture: RAM16K delegating to the built-in RAM16K.
// Expected result: PASS - proves the big-RAM step script (boundary and
// per-bank addresses) does not fail a correct chip.
CHIP RAM16K {
    IN in[16], load, address[14];
    OUT out[16];
    PARTS:
    RAM16K(in=in, load=load, address=address, out=out);
}

// Self-check fixture: Add16 that is correct except that bit 15 of the sum is
// forced to 1.  Expected result: FAIL - proves the wide-bus comparison is
// sensitive to a single wrong bit.
CHIP Add16 {
    IN a[16], b[16];
    OUT out[16];
    PARTS:
    Add16(a=a, b=b, out[0..14]=out[0..14]);
    Not(in=false, out=out[15]);
}

